(function ({ cookieName, decodedPixelUrl, debugLevel = 0 }) {
  const MAX_SYNC_ATTEMPTS = 2;
  const SYNC_RETRY_DELAY = 5; // Retry delay in ms
  const COOKIE_CHECK_INTERVAL = 10; // Check every 10ms
  const MAX_COOKIE_CHECKS = 20; // Maximum number of cookie checks
  let syncAttempts = 0;
  let cookieCheckCount = 0;

  /**
   * Main pixel synchronization handler
   * Creates an image element to trigger the pixel sync request and manages retry logic
   * Orchestrates the complete synchronization workflow including error recovery
   * 
   * Flow: Load pixel URL -> Wait for response -> Check for cookie -> Communicate results
   */
  function handlePixelSync() {
    const img = new Image();

    img.onload = function () {
      logInfo(
        `Pixel sync loaded, checking for cookie value "${cookieName}" every ${COOKIE_CHECK_INTERVAL}ms`,
      );

      // Use setTimeout instead of setInterval in case of an error been thrown,
      // it will not cause the script run forever.
      let cookieCheckTimeoutId;
      const cookieCheckTimeout = () => {
        // Clear any existing timeout first
        if (cookieCheckTimeoutId) {
          clearTimeout(cookieCheckTimeoutId);
          cookieCheckTimeoutId = null;
        }

        if (checkCookieValue(cookieName)) {
          // Cookie found, stop checking
          return;
        } else {
          // Schedule next check
          cookieCheckTimeoutId = setTimeout(cookieCheckTimeout, COOKIE_CHECK_INTERVAL);
        }
      };
      // Start the first check
      cookieCheckTimeoutId = setTimeout(cookieCheckTimeout, COOKIE_CHECK_INTERVAL);
    };

    img.onerror = function () {
      logError('Pixel sync failed, attempt:', syncAttempts + 1);

      if (syncAttempts < MAX_SYNC_ATTEMPTS) {
        syncAttempts++;
        logInfo('Retrying pixel sync in', SYNC_RETRY_DELAY, 'ms');
        setTimeout(handlePixelSync, SYNC_RETRY_DELAY);
      } else {
        window.parent.postMessage(
          {
            type: 'MOBKOI_PIXEL_SYNC_ERROR',
            error: 'Failed to load pixel after maximum attempts',
          },
          '*',
        );
      }
    };

    // Generate cache buster to prevent caching issues
    // Ensures each pixel request is unique and bypasses browser/proxy caches
    // Using crypto.getRandomValues() for better security than Math.random()
    const randomBytes = new Uint8Array(4);
    crypto.getRandomValues(randomBytes);
    const cacheBuster = Array.from(randomBytes, byte => byte.toString(36)).join('');
    const urlWithCacheBuster =
      decodedPixelUrl +
      (decodedPixelUrl.includes('?') ? '&' : '?') +
      '_cb=' +
      cacheBuster;

    // Set the source to trigger the sync
    img.src = urlWithCacheBuster;
  }

  /**
   * Function to get the cookie value by name
   */
  function getCookie(name) {
    // Add a leading semicolon to ensure the split works correctly
    const cookieString = '; ' + document.cookie;
    const parts = cookieString.split('; ' + name + '=');

    // If the cookie is found, return its value
    if (parts.length === 2) {
      const cookieValue = parts.pop().split(';').shift();
      return cookieValue;
    }

    // Return null if the cookie is not found
    return null;
  }

  /**
   * Cookie detection and communication function
   * Checks for the target cookie and communicates results to parent window
   * Implements timeout mechanism to prevent infinite checking
   * @param {string} cookieName - Name of the cookie to check for
   * @returns {boolean} - True if processing should stop, false to continue
   */
  function checkCookieValue(cookieName) {
    const cookieValue = getCookie(cookieName);
    if (cookieValue) {
      window.parent.postMessage(
        {
          type: 'MOBKOI_PIXEL_SYNC_COMPLETE',
          syncData: cookieValue,
        },
        '*',
      );
      logInfo(
        `Found cookie value "${cookieName}" in iframe: "${cookieValue}" after checking cookie ${cookieCheckCount + 1} times.`,
      );
      return true;
    }

    cookieCheckCount++;
    if (cookieCheckCount >= MAX_COOKIE_CHECKS) {
      logError(
        `Failed to find ${cookieName} in cookies after maximum attempts (${MAX_COOKIE_CHECKS})`,
      );
      window.parent.postMessage(
        {
          type: 'MOBKOI_PIXEL_SYNC_ERROR',
          error: `Failed to find ${cookieName} in cookies after maximum attempts (${MAX_COOKIE_CHECKS})`,
          syncData: null,
        },
        '*',
      );
      return true;
    }

    return false;
  }

  /**
   * Debug logging function for informational messages
   * Respects debugLevel configuration for controlled logging
   * @param {...*} args - Arguments to log
   */
  function logInfo(...args) {
    if (debugLevel >= 2) { // Info level and above
      console.log('Pixel Sync Iframe:', ...args);
    }
  }

  /**
   * Debug logging function for error messages
   * Always logs errors regardless of debug level for critical visibility
   * @param {...*} args - Arguments to log
   */
  function logError(...args) {
    if (debugLevel >= 1) { // Error level and above
      console.error('Pixel Sync Iframe:', ...args);
    }
  }

  // Start pixel sync immediately
  handlePixelSync();
